import React from 'react';
import { useEffect, useRef, useState } from 'react';
import { Coffee, MapPin, Clock, Phone, Leaf } from 'lucide-react';
import PhotoSlot from './components/PhotoSlot';

const serifFont = "'Noto Serif KR', serif";

function useReveal() {
  const ref = useRef<HTMLElement | null>(null);
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { threshold: 0.25 },
    );

    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  return { ref, visible };
}

function App() {
  const hero = useReveal();
  const ch1 = useReveal();
  const ch2 = useReveal();
  const ch3 = useReveal();

  const revealStyle = (visible: boolean): React.CSSProperties => ({
    opacity: visible ? 1 : 0,
    transform: visible ? 'translateY(0)' : 'translateY(24px)',
    transition: 'opacity 600ms ease-out, transform 600ms ease-out',
  });

  return (
    <div>
      {/* 히어로 */}
      <section
        data-slot="hero"
        ref={hero.ref as any}
        style={{
          height: '100vh',
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'center',
          padding: '0 32px',
        }}
      >
        <div className="cr-page cr-stack-24" style={revealStyle(hero.visible)}>
          <PhotoSlot ratio="16/9" showCaption style={{ maxHeight: 200 }} />
          <div className="cr-stack-16">
            <span className="cr-row-8 cr-eyebrow">
              <Coffee size={14} />
              MOWOL COFFEE
            </span>
            <h1 style={{ fontFamily: serifFont, fontSize: 56, fontWeight: 600, lineHeight: 1.3, margin: 0 }}>
              한 잔의 여유, 동네에서 만나요
            </h1>
            <p className="cr-body" style={{ color: 'var(--muted)' }}>
              원두 본연의 맛을 정성껏 내리는 작은 커피집, 모월 커피예요.
            </p>
          </div>
          <div>
            <button className="cr-btn lg">
              <MapPin size={18} />
              오시는 길 보기
            </button>
          </div>
        </div>
      </section>

      {/* 챕터 1 — 원두 이야기 (이미지 왼쪽) */}
      <section
        data-slot="ch1"
        ref={ch1.ref as any}
        style={{ height: '100vh', display: 'flex', alignItems: 'center' }}
      >
        <div
          className="cr-page"
          style={{
            display: 'flex',
            gap: 48,
            alignItems: 'center',
            flexWrap: 'wrap',
            ...revealStyle(ch1.visible),
          }}
        >
          <div style={{ flex: '1 1 320px' }}>
            <PhotoSlot ratio="4/3" showCaption />
          </div>
          <div className="cr-stack-16" style={{ flex: '1 1 320px' }}>
            <span className="cr-row-8 cr-eyebrow">
              <Leaf size={14} />
              원두 이야기
            </span>
            <h2 style={{ fontFamily: serifFont, fontSize: 56, fontWeight: 600, margin: 0, lineHeight: 1.35 }}>
              매주 직접 로스팅하는 원두
            </h2>
            <p className="cr-body" style={{ color: 'var(--muted)' }}>
              에티오피아, 콜롬비아 등 산지 고유의 향을 살려 소량씩 로스팅해요.
              내린 지 오래된 커피는 절대 내어드리지 않아요.
            </p>
          </div>
        </div>
      </section>

      {/* 챕터 2 — 공간 소개 (이미지 오른쪽) */}
      <section
        data-slot="ch2"
        ref={ch2.ref as any}
        style={{ height: '100vh', display: 'flex', alignItems: 'center' }}
      >
        <div
          className="cr-page"
          style={{
            display: 'flex',
            gap: 48,
            alignItems: 'center',
            flexWrap: 'wrap-reverse',
            ...revealStyle(ch2.visible),
          }}
        >
          <div className="cr-stack-16" style={{ flex: '1 1 320px' }}>
            <span className="cr-row-8 cr-eyebrow">
              <Coffee size={14} />
              공간 소개
            </span>
            <h2 style={{ fontFamily: serifFont, fontSize: 56, fontWeight: 600, margin: 0, lineHeight: 1.35 }}>
              혼자여도, 함께여도 편안한 자리
            </h2>
            <p className="cr-body" style={{ color: 'var(--muted)' }}>
              창가 자리에서 여유롭게 책을 읽거나, 친구와 도란도란 이야기 나누기 좋은
              열두 평 남짓한 아늑한 공간이에요.
            </p>
          </div>
          <div style={{ flex: '1 1 320px' }}>
            <PhotoSlot ratio="4/3" showCaption />
          </div>
        </div>
      </section>

      {/* 챕터 3 — 오시는 길 · 연락처 (이미지 왼쪽) */}
      <section
        data-slot="ch3"
        ref={ch3.ref as any}
        style={{ height: '100vh', display: 'flex', alignItems: 'center' }}
      >
        <div
          className="cr-page"
          style={{
            display: 'flex',
            gap: 48,
            alignItems: 'center',
            flexWrap: 'wrap',
            ...revealStyle(ch3.visible),
          }}
        >
          <div style={{ flex: '1 1 320px' }}>
            <PhotoSlot ratio="4/3" showCaption />
          </div>
          <div className="cr-stack-24" style={{ flex: '1 1 320px' }}>
            <div className="cr-stack-16">
              <span className="cr-row-8 cr-eyebrow">
                <MapPin size={14} />
                오시는 길
              </span>
              <h2 style={{ fontFamily: serifFont, fontSize: 56, fontWeight: 600, margin: 0, lineHeight: 1.35 }}>
                동네 골목, 모월 커피
              </h2>
            </div>

            <div className="cr-card cr-stack-16">
              <div className="cr-row-8">
                <MapPin size={16} color="var(--muted)" />
                <span className="cr-body">서울시 마포구 동교로 45길 12</span>
              </div>
              <div className="cr-row-8">
                <Clock size={16} color="var(--muted)" />
                <span className="cr-body">매일 오전 9시 — 오후 9시 (월요일 휴무)</span>
              </div>
              <div className="cr-row-8">
                <Phone size={16} color="var(--muted)" />
                <span className="cr-body">0507-1234-5678</span>
              </div>
            </div>

            <button className="cr-btn lg">
              <Phone size={18} />
              전화로 문의하기
            </button>
          </div>
        </div>
      </section>
    </div>
  );
}

export default App;

