import { ImageIcon } from 'lucide-react';
import type { CSSProperties } from 'react';

function PhotoSlot({
  ratio,
  showCaption,
  style,
}: {
  ratio: '16/9' | '4/3';
  showCaption?: boolean;
  style?: CSSProperties;
}) {
  return (
    <div
      style={{
        aspectRatio: ratio,
        maxHeight: 200,
        width: '100%',
        background: 'var(--accent-soft)',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        gap: 8,
        borderRadius: 10,
        ...style,
      }}
    >
      <ImageIcon size={28} color="var(--muted)" strokeWidth={1.5} />
      {showCaption && (
        <span className="cr-caption" style={{ color: 'var(--muted)' }}>
          사진을 보내주시면 여기에 넣어드릴게요
        </span>
      )}
    </div>
  );
}

export default PhotoSlot;
